#!/usr/bin/env node
// Turns approved spoken-guidance recordings into app assets (and, when
// marked, website samples). Only recordings listed in
// assets/prompts/approved.json, with a transcript and a named reviewer,
// are included. Anything else is ignored, so the app never labels a prompt
// available without a reviewed recording behind it.
//
//   npm run prompts:sync           regenerate
//   npm run prompts:sync -- --check   fail if the generated files are stale
import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, extname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const mobile = join(dirname(fileURLToPath(import.meta.url)), '..');
const repo = join(mobile, '..');
const { PROMPT_TEXT } = await import('../src/voice/prompts.ts');

const LANGS = { en: ['English', 'English'], yo: ['Yoruba', 'Yorùbá'], ha: ['Hausa', 'Hausa'], ig: ['Igbo', 'Igbo'], pcm: ['Nigerian Pidgin', 'Naijá'] };
const EXTS = new Set(['.m4a', '.mp3', '.wav', '.aac']);
const check = process.argv.includes('--check');

const approvedPath = join(mobile, 'assets', 'prompts', 'approved.json');
const approved = JSON.parse(readFileSync(approvedPath, 'utf8'));
const errors = [];
const seen = new Set();
const byLang = {};
const webSamples = [];

for (const [i, r] of (approved.recordings ?? []).entries()) {
  const where = `recordings[${i}]`;
  if (!LANGS[r.language]) errors.push(`${where}: unknown language "${r.language}"`);
  if (!(r.prompt in PROMPT_TEXT)) errors.push(`${where}: unknown prompt "${r.prompt}"`);
  if (!r.file || !EXTS.has(extname(r.file).toLowerCase())) errors.push(`${where}: file must be .m4a, .mp3, .wav or .aac`);
  else if (!existsSync(join(mobile, 'assets', 'prompts', r.file))) errors.push(`${where}: missing file assets/prompts/${r.file}`);
  if (!r.transcript?.trim()) errors.push(`${where}: transcript is required`);
  if (!r.reviewedBy?.trim()) errors.push(`${where}: reviewedBy is required (the native speaker who approved it)`);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(r.reviewedOn ?? '')) errors.push(`${where}: reviewedOn must be YYYY-MM-DD`);
  const key = `${r.language}/${r.prompt}`;
  if (seen.has(key)) errors.push(`${where}: duplicate recording for ${key}`);
  seen.add(key);
  (byLang[r.language] ??= {})[r.prompt] = r;
}
if (errors.length) {
  console.error('approved.json has problems:\n  ' + errors.join('\n  '));
  process.exit(1);
}

const q = (s) => JSON.stringify(s);
let body = '';
for (const [lang, prompts] of Object.entries(byLang)) {
  body += `  ${lang}: {\n`;
  for (const [id, r] of Object.entries(prompts)) {
    body += `    ${id}: { source: require('../../assets/prompts/${r.file}'), transcript: ${q(r.transcript)}, reviewedBy: ${q(r.reviewedBy)}, reviewedOn: ${q(r.reviewedOn)} },\n`;
    if (r.website) {
      const name = `${lang}-${id}${extname(r.file).toLowerCase()}`;
      webSamples.push({
        language: lang,
        languageName: LANGS[lang][0],
        nativeName: LANGS[lang][1],
        prompt: id,
        english: PROMPT_TEXT[id],
        transcript: r.transcript,
        src: `/voices/${name}`,
        file: r.file,
        reviewedOn: r.reviewedOn,
      });
    }
  }
  body += '  },\n';
}

const generated = `// GENERATED by scripts/sync-prompts.mjs from assets/prompts/approved.json.
// Do not edit by hand. Run \`npm run prompts:sync\` after adding recordings.
import type { LanguageCode } from '@/profile/profile';
import type { PromptId } from './prompts';

export interface PromptRecording {
  source: number;
  transcript: string;
  reviewedBy: string;
  reviewedOn: string;
}

export const PROMPT_RECORDINGS: Partial<Record<LanguageCode, Partial<Record<PromptId, PromptRecording>>>> = {${body ? '\n' + body : ''}};
`;

const outPath = join(mobile, 'src', 'voice', 'promptAssets.generated.ts');
const webJsonPath = join(repo, 'web', 'src', 'content', 'voice-samples.json');
const webJson = JSON.stringify(webSamples.map(({ file, ...s }) => s), null, 2) + '\n';

if (check) {
  const stale = readFileSync(outPath, 'utf8') !== generated || (existsSync(webJsonPath) && readFileSync(webJsonPath, 'utf8') !== webJson);
  if (stale) {
    console.error('Generated prompt files are out of date. Run: npm run prompts:sync');
    process.exit(1);
  }
  console.log('Prompt assets are up to date.');
  process.exit(0);
}

writeFileSync(outPath, generated);
if (existsSync(join(repo, 'web'))) {
  mkdirSync(dirname(webJsonPath), { recursive: true });
  writeFileSync(webJsonPath, webJson);
  mkdirSync(join(repo, 'web', 'public', 'voices'), { recursive: true });
  for (const s of webSamples) copyFileSync(join(mobile, 'assets', 'prompts', s.file), join(repo, 'web', 'public', s.src));
}
const total = Object.values(byLang).reduce((n, p) => n + Object.keys(p).length, 0);
console.log(`Synced ${total} approved recording(s); ${webSamples.length} published as website samples.`);
